import{z as E,x as n,o as t,c as h,q as o,j as p,D as e,d as s,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"随机性良率","description":"","frontmatter":{"title":"随机性良率","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/stochastic-yield.md","filePath":"litho/stochastic-yield.md","lastUpdated":1791063341000}'),d={name:"litho/stochastic-yield.md"};function c(A,a,B,m,_,N){const i=n("Mermaid");return t(),h("div",null,[a[2]||(a[2]=o('<h1 id="随机性良率" tabindex="-1">随机性良率 <a class="header-anchor" href="#随机性良率" aria-label="Permalink to &quot;随机性良率&quot;">​</a></h1><div class="epigraph"><p>EUV 的缺孔与桥连可以在无颗粒、OPC 绿灯时仍按光子与分子计数抽签；这笔良率不进 Poisson 颗粒账，而进随机窗。</p><footer>—— 对照 De Bisschop / Naulleau 对随机失效的公开论述；[随机工艺窗口](/litho/stochastic-process-window) 已切第二张窗</footer></div><p><a href="/litho/systematic-vs-random-defects">上一课</a>拆开系统与随机。缺口是随机内部：颗粒关键面积解释不了「同一孔阵列、剂量仍在均值窗内」的打开失败。<a href="/litho/stochastic-process-window">随机窗</a> 与 <a href="/litho/stochastic-z-factor">z 因子</a> 已有物理；本课钉它如何进良率，不重推 RLS 三角。光学与电子束如何看见这些缺陷，留给<a href="/litho/defect-inspection-optical-ebeam">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机性良率：\\(Y_\\mathrm{stoch} \\approx (1-p)^N\\)，孔或线端独立失败率 \\(p\\)，特征数 \\(N\\)。\\(N\\) 在 SRAM 和 via 阵列上巨大，于是 \\(p\\) 必须极小。剂量、NILS、酸分子数推 \\(p\\)；这与颗粒 \\(D\\) 独立相乘。把缺孔当颗粒去抓洁净，ROI 为零。</p>',5)),(t(),p(l,null,{default:e(()=>[r(i,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHIP%5B%22%E6%95%B4%E7%89%87%E8%89%AF%E7%8E%87%22%5D%20--%3E%20DUST%5B%22%E9%A2%97%E7%B2%92%E9%A1%B9%3A%20%E7%BC%BA%E9%99%B7%E5%AF%86%E5%BA%A6%20%C3%97%20%E5%85%B3%E9%94%AE%E9%9D%A2%E7%A7%AF%22%5D%0A%20%20CHIP%20--%3E%20STO%5B%22%E9%9A%8F%E6%9C%BA%E9%A1%B9%3A%20(1-p)%5EN%22%5D%0A%20%20STO%20--%3E%20NBIG%5B%22SRAM%20%2F%20via%20%E9%98%B5%E5%88%97%20N%20%E5%B7%A8%E5%A4%A7%22%5D%0A%20%20NBIG%20--%3E%20PS%5B%22p%20%E5%BF%85%E9%A1%BB%E5%8E%8B%E5%88%B0%20ppb%20%E7%BA%A7%22%5D%0A%20%20PS%20--%3E%20LEVER%5B%22%E6%97%8B%E9%92%AE%3A%20%E5%89%82%E9%87%8F%20%2F%20NILS%20%2F%20%E6%9D%90%E6%96%99%20z%22%5D%0A%20%20DUST%20--%3E%20MULT%5B%22%E4%B8%A4%E9%A1%B9%E7%8B%AC%E7%AB%8B%E7%9B%B8%E4%B9%98%22%5D%0A%20%20STO%20--%3E%20MULT%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p><span class="marginnote">数字实例：设单孔失败率 \\(p=10^{-9}\\)，一亿个孔 \\(N=10^8\\)，则 \\(Y \\approx (1-10^{-9})^{10^8} \\approx e^{-0.1} \\approx 90\\%\\)，尚可；但 SRAM 阵列 \\(N=10^{10}\\) 时同一 \\(p\\) 给 \\(e^{-10} \\approx 4.5\\times 10^{-5}\\)——缓存几乎全灭。\\(N\\) 大一位数，\\(p\\) 就得多压一位数。</span></p><p><span class="marginnote">「ppb」翻译一下：parts per billion，十亿分之一。随机缺陷规格常在这个量级——相当于全中国人口里只允许个位数的人出错，所以靠事后抓缺陷救不了，只能从剂量与材料上压 \\(p\\) 本身。</span></p><p>缺口是<strong>统计合同</strong>，不是再写蒙特卡洛。量产要规定：随机缺陷规格（ppb 级）、如何抽检（电子束点数）、以及剂量下限不得为产能突破随机窗。</p><h3 id="与-ler-平滑的关系" tabindex="-1">与 LER 平滑的关系 <a class="header-anchor" href="#与-ler-平滑的关系" aria-label="Permalink to &quot;与 LER 平滑的关系&quot;">​</a></h3><p>转印平滑可降 LER 3σ，不降缺孔 \\(p\\)。拓扑事件与边粗糙是不同阶。报表只写 LWR 会假装随机良率已好。</p><p><span class="marginnote">系统热点处 \\(p\\) 升高，看起来像「随机很多」。先修 NILS，再报 \\(Y_\\mathrm{stoch}\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计 \\(p\\)：电子束抽检阵列、电学 via 链、SRAM 位失败分类。外推到全芯片 \\(N\\)。与 PWQ：过程角上 \\(p(E,z)\\) 的等高线即随机窗。与剂量：光子预算课已有；本课要求良率 Pareto 单列 stoch。重工对光子随机几乎无效（换一组抽签），分派课已预警。</p><p>\\(N\\) 要用设计里的实际孔/线端数，而不是芯片面积。De Bisschop 与 Naulleau 的公开论述都把失败当成特征事件；本课把这句话写成良率公式的 \\(N\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Bernoulli 试验在弱相关时用独立近似；相关长度课说明邻近孔可能相关，则有效 \\(N\\) 下降、方差变，负二项又出现——但是化学簇而不是颗粒簇。剂量升降低 \\(p\\)、伤吞吐与损伤。材料换 z 因子。这些旋钮都不在 CMP dummy 里。</p>',11)),(t(),p(l,null,{default:e(()=>[r(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%8D%95%E7%89%B9%E5%BE%81%E5%A4%B1%E8%B4%A5%E7%8E%87%20p%22%5D%20--%3E%20Y%5B%22(1-p)%5EN%22%5D%0A%20%20N%5B%22%E7%89%B9%E5%BE%81%E6%95%B0%20N%22%5D%20--%3E%20Y%0A%20%20NIL%5B%22NILS%20%2F%20%E5%89%82%E9%87%8F%20%2F%20%E6%9D%90%E6%96%99%22%5D%20--%3E%20P%0A%20%20Y%20--%3E%20PAR%5B%22Pareto%20%E5%8D%95%E5%88%97%20stoch%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p>p 与 N 来自特征事件，不是芯片外形面积。剂量下限由随机窗约束，不能为产能往下探。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重写二次电子全文。不编造某节点 ppb 数字。DUV 随机通常不是主导，但薄胶高 NA 不要假装为零。</p><p>后课默认：\\(Y_\\mathrm{stoch}\\) 单列，与颗粒相乘。下一课检测必须能看见这些小事件，否则 Pareto 是盲的。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光子/化学随机是 Bernoulli 特征失败，不是颗粒 \\(DA\\)。</li><li>阵列 \\(N\\) 迫使 \\(p\\) 进 ppb；剂量下限受随机窗约束。</li><li>重工几乎不救光子抽签。</li><li>系统热点处 \\(p\\) 升高，应先修 NILS 再报随机良率。</li><li>出处：De Bisschop、Naulleau 随机失效公开论述；Mack 随机窗衔接。</li></ul>',6))])}const f=E(d,[["render",c]]);export{D as __pageData,f as default};
